function translateUiText(text){
  const original=text.trim(),languageIndex=uiLanguage==='en'?1:0;
  if(salesTerminology[original])return text.replace(original,salesTerminology[original][languageIndex]);
  const navigation=original.match(/^([◫♙↗⚡✉⚙⌕✧\s]+)(.+)$/u);
  if(navigation&&salesTerminology[navigation[2]])return text.replace(original,navigation[1]+salesTerminology[navigation[2]][languageIndex]);
  const breadcrumb=original.match(/^Przestrzeń robocza \/ (.+)$/);
  if(breadcrumb&&salesTerminology[breadcrumb[1]])return (uiLanguage==='en'?'Workspace / ':'Przestrzeń robocza / ')+salesTerminology[breadcrumb[1]][languageIndex];
  if(uiLanguage!=='en')return text;
  const source=text.trim();
  let value=uiEnglish[source];
  if(value===undefined){
    const rules=[
      [/^Krok (\d+): dzień (\d+)$/,(_,n,day)=>'Step '+n+': day '+day],
      [/^Wybrano (\d+) aktywnych kontaktów\.$/,(_,n)=>n+' active contacts selected.'],
      [/^(Kapitał|Wzrost|Zespół|Ekspansja|Produkt|Technologia|Intencja|Aktywność) · (.+)$/,(_,category,label)=>(uiEnglish[category]||category)+' · '+(uiEnglish[label]||label)],
      [/^Do przygotowania zostaną użyte aktywne kontakty z bazy: (\d+)\.$/,(_,n)=>'Active contacts to prepare messages for: '+n+'.'],
      [/^Wybrane kontakty \((\d+)\)$/,(_,n)=>'Selected contacts ('+n+')'],
      [/^([◫♙↗⚡✉⚙⌕]+\s*)(Przegląd|Znajdź klientów|Kontakty|Kampanie|Sygnały|Odpowiedzi|Biblioteka|Integracje)$/,(_,icon,label)=>icon+uiEnglish[label]],
      [/^Przestrzeń robocza \/ (.+)$/,(_,label)=>'Workspace / '+(uiEnglish[label]||label)],
      [/^Wiadomości · (\d+)$/,(_,n)=>'Messages · '+n],
      [/^Wiadomość · krok (\d+)$/,(_,n)=>'Message · step '+n],
      [/^Krok (\d+) z (\d+)$/,(_,n,total)=>'Step '+n+' of '+total],
      [/^✉ Email · krok (\d+)$/,(_,n)=>'✉ Email · step '+n],
      [/^Wiadomość (\d+)$/,(_,n)=>'Message '+n],
      [/^(\d+) osób$/,(_,n)=>n+' people'],
      [/^Podłącz (.+)$/,(_,name)=>'Connect '+name],
      [/^Wyniki gotowe do przeglądu$/,()=> 'Results ready for review'],
      [/^Odczyt oferty nadawcy$/,()=> 'Reading the sender’s offer'],
      [/^Wyszukiwanie firm w Hunter Discover$/,()=> 'Finding companies in Hunter Discover'],
      [/^Szukanie osób: (.+)$/,(_,name)=>'Finding people: '+name],
      [/^Weryfikacja: (.+)$/,(_,name)=>'Verifying: '+name],
      [/^Szkice gotowe do sprawdzenia$/,()=> 'Drafts ready for review'],
      [/^Pobrano: (.+)$/,(_,value)=>'Retrieved: '+value.replace('Zapytanie weryfikacji:', 'Verification request:').replace('Weryfikacja dostawcy:', 'Provider verification:')]
    ];
    for(const [pattern,replacer]of rules)if(pattern.test(source)){value=source.replace(pattern,replacer);break}
  }
  return value===undefined?text:text.replace(source,value);
}
function isUiText(node){
  const el=node.parentElement;if(!el||el.closest('script,style,textarea,code,pre,[data-no-translate],.message,.mail-preview,#builder-preview-content .preview-material,#builder-campaign-title,.recipient-picker strong,.recipient-picker small,#project-picker option:not([value=""]),#preview-contact option'))return false;
  if(el.closest('.prospect-card p,.prospect-card h3,.prospect-card small,.signal-card p,.signal-card strong,.activity,.builder-summary dd,tbody td')&&!el.closest('button,.badge,label,.error,summary,.discover-contact-panel .hint,.discover-contact-panel .notice')&&!el.matches('.prospect-card p>strong'))return false;
  return true;
}
function localizeUi(){
  uiObserver.disconnect();
  document.documentElement.lang=uiLanguage;
  document.title=uiLanguage==='en'?'Kaśka — sales workspace':'Kaśka — centrum sprzedaży';
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const node=walker.currentNode;if(!isUiText(node))continue;
    let record=originalUiText.get(node);
    if(!record||record.last!==node.textContent)record={source:node.textContent};
    record.last=translateUiText(record.source);
    if(node.textContent!==record.last)node.textContent=record.last;
    originalUiText.set(node,record);
  }
  for(const el of document.querySelectorAll('[placeholder],[aria-label]')){
    let records=originalUiAttributes.get(el)||{};
    for(const attr of ['placeholder','aria-label'])if(el.hasAttribute(attr)){
      let record=records[attr];const current=el.getAttribute(attr);
      if(!record||record.last!==current)record={source:current};
      record.last=translateUiText(record.source);el.setAttribute(attr,record.last);records[attr]=record;
    }
    originalUiAttributes.set(el,records);
  }
  document.querySelectorAll('[data-ui-language]').forEach(el=>el.value=uiLanguage);
  uiObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
}
const uiObserver=new MutationObserver(()=>localizeUi());
function applyUiLanguage(language){
  const changed=uiLanguage!==(language==='en'?'en':'pl');
  uiLanguage=language==='en'?'en':'pl';
  try{localStorage.setItem('kaska-ui-language',uiLanguage)}catch{}
  if(changed&&typeof renderDashboardActivity==='function')renderDashboardActivity();
  if(changed&&typeof dashboardFlowPanel==='function'){const flow=document.querySelector('.dashboard-flow');if(flow)flow.outerHTML=dashboardFlowPanel()}
  if(changed&&typeof renderReports==='function'&&view==='reports')renderReports();
  if(changed&&typeof render==='function'&&view==='dashboard'&&state)render();
  localizeUi();
}
function syncLanguages(){
  if(state.preferences)applyUiLanguage(state.preferences.ui_language);
}
function messageLanguageOptions(selected){return Object.entries(state.languages).map(([code,spec])=>`<option value="${code}" ${code===selected?'selected':''}>${spec.label}</option>`).join('')}
function renderLanguageSettings(){
  $('#content .topline').insertAdjacentHTML('afterend',`<section class="panel"><h2>Języki</h2><p>Język Kaśki zmienia panel i język nowych ocen AI. Język wiadomości wybierasz niezależnie dla każdej kampanii.</p><div class="row"><div><label for="settings-ui-language">Język Kaśki</label><select id="settings-ui-language" data-ui-language><option value="pl">Polski</option><option value="en">English</option></select></div><div><label for="settings-message-language">Domyślny język wiadomości</label><select id="settings-message-language">${messageLanguageOptions(state.preferences.message_language)}</select></div></div><p class="hint">Bez AI wpisz ofertę i własne szablony w wybranym języku. Treści wpisane przez Ciebie nie są automatycznie tłumaczone.</p></section>`);
  $('#settings-message-language').onchange=e=>run(e.target,async()=>{
    try{state.preferences=await api('preferences',{message_language:e.target.value});toast('Zapisano domyślny język wiadomości.')}
    finally{e.target.value=state.preferences.message_language}
  });
}
document.addEventListener('change',e=>{
  if(!e.target.matches('[data-ui-language]'))return;
  run(e.target,async()=>{try{state.preferences=await api('preferences',{ui_language:e.target.value});applyUiLanguage(state.preferences.ui_language);toast('Zapisano język Kaśki.')}finally{e.target.value=state.preferences.ui_language}});
});
document.addEventListener('DOMContentLoaded',()=>applyUiLanguage(uiLanguage));
window.addEventListener('hashchange',()=>{
  const next=location.hash.slice(1);
  if(['dashboard','discover','prospecting','contacts','campaigns','signals','inbox','library','reports','settings','administration','project'].includes(next)){
    view=next;selectedCampaign=null;render();
  }
});

function changeBuilderLanguage(){
  const select=$('#build-language'),previous=state.languages[select.dataset.previousLanguage],next=state.languages[select.value];
  document.querySelectorAll('#steps .step').forEach((row,i)=>{
    const subject=row.querySelector('[name=subject]'),body=row.querySelector('[name=body]');
    if(subject.value===(i?previous.follow_subject:previous.subject))subject.value=i?next.follow_subject:next.subject;
    if(body.value===(i?previous.follow_body:previous.body))body.value=i?next.follow_body:next.body;
  });
  select.dataset.previousLanguage=select.value;persistBuilder();
  toast('Język wiadomości zmieniony. Własną treść sprawdź lub przetłumacz przed wysyłką.');
}
